        IClassFile cf2 = pack.getClassFile("AnotherFile.class");
        doSomethingWithClassFile(cf2);

        // Also works with a cast
        IClassFile cf3 = ((IPackageFragment) pack).getClassFile("YetAnother.class");
    }

